    <header class="next-article-header next-shell"><p class="next-byline"><?= e($news['category'] ?? '') ?> · <?= e(date('d M Y', strtotime($news['published_at'] ?? $news['created_at']))) ?></p><h1><?= e($news['title']) ?></h1><?php if (!empty($news['excerpt'])): ?><p class="next-deck"><?= e(PublicTheme::summary($news['excerpt'])) ?></p><?php endif; ?><p class="next-byline"><?= e($news['author_name'] ?? '') ?></p></header>
